metadata.preview:
[
  {
    "status": "finished",
    "data": {
      "title": "Unauthenticated osTicket installer exposed",
      "cvss": "CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
      "summary": "Anyone on the internet can open the ticket system’s installation wizard and finish setup themselves.",
      "description": "ticket.ausecurity.best is an osTicket v1.18.4 instance that has not been installed. Unauthenticated GET requests to /setup/install.php and /setup/ return HTTP 200 and the osTicket prerequisites wizard (PHP/MySQL checks passing, continue form present, PHPSESSID cookie set). Application paths including /scp/login.php, /login.php, /kb/, and /api/http.php all HTTP 302 to /setup/install.php, confirming the product is in pre-install state rather than a leftover file on a live helpdesk. The same installer is also served in cleartext on TCP 8080 (Apache/2.4.68, PHP/8.2.33). Completing the wizard was not performed. If completed by an attacker, they could choose the admin account and database settings and take full control of the future support platform, including customer tickets.",
      "recommendation": "Take the host offline until osTicket is installed privately. Restrict /setup/ to localhost or remove the setup directory after install. Require HTTPS only and close TCP 8080 if it is not needed. Place the helpdesk behind authentication and a firewall allowlist where possible.",
      "affected_components": [
        "https://ticket.ausecurity.best/",
        "https://ticket.ausecurity.best/setup/",
        "https://ticket.ausecurity.best/setup/install.php",
        "http://51.79.166.209:8080/setup/install.php"
      ],
      "references": [
        "https://docs.osticket.com/en/latest/Getting%20Started/Installation.html"
      ]
    }
  },

